mapper.select:
SELECT s.*, c.color_name, c.status as color_status, c.remarks as color_remarks, b.brand_name, b.status as brand_status, b.remarks as brand_remarks, t.type_name, t.status as type_status FROM shoes s LEFT JOIN colors c ON s.color_id = c.color_id LEFT JOIN brands b ON s.brand_id = b.brand_id LEFT JOIN types t ON s.type_id = t.type_id
AND s.brand_id = #{brandId}
AND s.type_id = #{typeId}
AND s.color_id = #{colorId}
AND s.status = #{status}
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR s.description LIKE CONCAT('%', #{keyword}, '%'))
AND s.price >= #{minPrice}
AND s.price <= #{maxPrice}
ORDER BY s.shoe_id DESC

